        lines.pop()
    state = 1
    radices = RADICES if SCHEME == 2 else BINARY_RADICES
    for line in lines:
        m = TEMPLATE.fullmatch(line)
        if m:
            a, b, c = map(int, m.groups())
            kind, value = 0, (a * 10**6 + b) * 10**9 + c
